mapper.select:
SELECT i.area AS area, i.current_handler_emp_no AS currentHandlerEmpNo, i.current_handler_emp_name AS currentHandlerEmpName, SUM(CASE WHEN i.status <> 'CLOSED' THEN 1 ELSE 0 END) AS openCount, COUNT(1) AS handledCount, SUM(CASE WHEN i.status <> 'CLOSED' AND i.submit_time < DATE_SUB(NOW(), INTERVAL #{overdueDays} DAY) THEN 1 ELSE 0 END) AS overdueCount FROM cps_issue i
i.current_handler_emp_no IS NOT NULL
AND i.status <> 'CLOSED' AND i.status = #{status}
AND i.status <> 'CLOSED' AND i.factory = #{factory} AND i.area = #{area} AND i.category_l1_id = #{categoryL1Id}
GROUP BY i.area, i.current_handler_emp_no, i.current_handler_emp_name ORDER BY openCount DESC, overdueCount DESC, i.area, i.current_handler_emp_no LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(1)
FROM (
  SELECT 1
  FROM cps_issue i

      i.current_handler_emp_no IS NOT NULL


              AND i.status <> 'CLOSED'
              AND i.status = #{status}


      AND i.status <> 'CLOSED'
      AND i.factory = #{factory}
      AND i.area = #{area}
      AND i.category_l1_id = #{categoryL1Id}

  GROUP BY i.area, i.current_handler_emp_no, i.current_handler_emp_name
) g

mapper.sql:
SELECT issue_id, COUNT(1) AS cnt, MAX(created_at) AS last_at
FROM cps_issue_flow_log
WHERE action = 'REOPEN'
  AND created_at >= #{startTime}
  AND created_at <= #{endTime}
GROUP BY issue_id
UNION ALL
SELECT issue_id, COUNT(1) AS cnt, MAX(created_at) AS last_at
FROM cps_review_adjudication
WHERE decision = 'REJECT'
  AND created_at >= #{startTime}
  AND created_at <= #{endTime}
GROUP BY issue_id

mapper.select:
SELECT i.id AS issueId, i.factory AS factory, i.area AS area, i.category_l1_id AS categoryL1Id, i.category_l2_id AS categoryL2Id, recur.cnt AS recurrenceCount, recur.lastAt AS lastRecurrenceAt FROM cps_issue i INNER JOIN ( SELECT issue_id, SUM(cnt) AS cnt, MAX(last_at) AS lastAt FROM () t GROUP BY issue_id HAVING SUM(cnt) >= #{threshold} ) recur ON recur.issue_id = i.id
AND i.category_l1_id = #{categoryL1Id}
ORDER BY recur.cnt DESC, recur.lastAt DESC, i.id DESC LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(1)
FROM cps_issue i
INNER JOIN (
  SELECT issue_id, SUM(cnt) AS cnt
  FROM () t
  GROUP BY issue_id
  HAVING SUM(cnt) >= #{threshold}
) recur ON recur.issue_id = i.id

    AND i.category_l1_id = #{categoryL1Id}

SELECT r.id AS roomId, r.room_name AS roomName, ii.id AS itemId, ii.item_name AS itemName, last_rc.last_record_at AS lastRecordAt, CASE WHEN last_rc.last_record_at IS NULL THEN NULL ELSE DATEDIFF(NOW(), last_rc.last_record_at) END AS daysSinceLastRecord FROM cps_room r CROSS JOIN cps_inspection_item ii LEFT JOIN ( SELECT room_id, MAX(submitted_at) AS last_record_at FROM cps_room_check_record WHERE submitted_at IS NOT NULL GROUP BY room_id ) last_rc ON last_rc.room_id = r.id
ii.enabled = 1 AND r.enabled = 1 AND (last_rc.last_record_at IS NULL OR last_rc.last_record_at < DATE_SUB(NOW(), INTERVAL #{gapDays} DAY)) AND r.factory = #{factory} AND r.room_type = #{storageRoomType}
ORDER BY daysSinceLastRecord IS NULL ASC, daysSinceLastRecord DESC, r.id, ii.id LIMIT #{limit} OFFSET #{offset}
